Translate("deDE", "ashenvale", {
	title = "Eschental",
	aliases = { "Wald von Eschental" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Eschental ist der große Wald der {link:night-elves}Nachtelfen{/link}, ein Land hoch aufragender Bäume, silberner Seen und weißer Ruinen im Norden von {link:kalimdor}Kalimdor{/link}. Es erstreckt sich vom grauen Meer am {link:the-zoram-strand}Zoramstrand{/link} im Westen bis zu dem Fluss, der es im Osten von {link:azshara}Azshara{/link} trennt. Die {link:darkshore}Dunkelküste{/link} und der {link:felwood}Teufelswald{/link} liegen im Norden, das {link:stonetalon-mountains}Steinkrallengebirge{/link} und {link:the-barrens}das Brachland{/link} im Süden. Zehntausend Jahre lang haben die Nachtelfen es als heiligen Wald bewahrt. Heilig ist es nicht mehr nur ihnen. Die Äxte der {link:horde}Horde{/link} schallen durch seine östlichen Täler, und der Wald ist zum ältesten und bittersten Schlachtfeld zwischen den Elfen und den {link:orcs}Orcs{/link} geworden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Bäume des Eschentals sind älter als jede Chronik. Vor der {link:great-sundering}Großen Teilung{/link} standen Städte der Elfen entlang seiner Westküste, und die Stadt {link:the-zoram-strand}Zoram{/link} blickte über das Meer. Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} zerstört wurde, stieg das Meer und verschlang Zoram, und die Ruinen der alten Tempel blieben verstreut in den Wäldern zurück: {link:the-ruins-of-ordil-aran}Ordil'Aran{/link}, {link:bathran-s-haunt}Bathrans Schlupfwinkel{/link}, die {link:the-ruins-of-stardust}Sternenstaubruinen{/link} und die Stadt {link:xavian}Xavian{/link} im Osten. Nach dem Krieg ließen sich die {link:night-elves}Nachtelfen{/link} im Schatten des {link:mount-hyjal}Berges Hyjal{/link} nieder und widmeten sich den Wegen des {link:cenarius}Cenarius{/link} und der Druiden. Während die Druiden im {link:emerald-dream}Smaragdgrünen Traum{/link} schliefen, wachten die {link:sentinels}Schildwachen{/link} von {link:tyrande-whisperwind}Tyrande Whisperwind{/link} durch die Zeitalter der Langen Wacht über den Wald. Keine Chronik verzeichnet, wann {link:astranaar}Astranaar{/link} oder die anderen Dörfer des Waldes zuerst errichtet wurden.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Eschental hat seit dem {link:third-war}Dritten Krieg{/link} keinen Frieden gekannt. Die {link:sentinels}Schildwachen{/link} halten {link:astranaar}Astranaar{/link}, {link:maestra-s-post}Maestras Posten{/link}, die {link:silverwind-refuge}Silberwindzuflucht{/link} und {link:forest-song}Forest Song{/link}, doch ihre Reihen sind dünn und ihre Wege lang. Die {link:furbolgs}Furbolgs{/link} der {link:thistlefur-village}Distelfelle{/link} und der Foulweald, einst Freunde der Elfen, wurden von einer Verderbnis vergiftet, die aus dem {link:felwood}Teufelswald{/link} herabkriecht, und sie fallen über jeden Reisenden her. {link:satyrs}Satyrn{/link} halten {link:night-run}Night Run{/link}, {link:satyrnaar}Satyrnaar{/link} und {link:xavian}Xavian{/link}. Die {link:naga}Naga{/link} sind zu den versunkenen Ruinen von {link:the-zoram-strand}Zoram{/link} zurückgekehrt, und ein Kult des {link:twilight-s-hammer}Schattenhammers{/link} sammelt sich in den überfluteten Hallen der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}. Im Osten schlagen die {link:orcs}Orcs{/link} der Warsong unter dem Schutz des Splintertreepostens Holz für die {link:horde}Horde{/link}. An der Westküste haben sie einen zweiten Außenposten errichtet, {link:zoram-gar-outpost}Zoram'gar{/link}. Die Elfen beantworten jeden gefällten Baum mit Pfeilen, und mit jeder Jahreszeit breitet sich der Krieg zwischen den beiden Völkern ein wenig weiter in die Wälder aus.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:night-elves}Nachtelfen{/link}.{/b} {link:sentinels}Schildwachen{/link}, Druiden und Priesterinnen, die die Dörfer des Waldes halten und darum kämpfen, ihn unversehrt zu bewahren.
• {b}Die Dryaden.{/b} Die Töchter des {link:cenarius}Cenarius{/link} tanzen noch immer auf den Lichtungen von {link:raynewood-retreat}Raynewood{/link} und am {link:the-shrine-of-aessina}Schrein von Aessina{/link}.
• {b}Die {link:horde}Horde{/link}.{/b} Die {link:orcs}Orcs{/link} der Warsong, mit Trollen, {link:tauren}Tauren{/link} und Goblins an ihrer Seite, halten den {link:splintertree-post}Splintertreeposten{/link}, die Holzfällerlager im Osten und den {link:zoram-gar-outpost}Zoram'gar-Außenposten{/link} an der Küste.
• {b}Die Verlassenen.{/b} Apotheker aus {link:undercity}Undercity{/link} haben sich in die Grabhügel und Ruinen der Elfen geschlichen.
• {b}Die {link:furbolgs}Furbolgs{/link}.{/b} Die {link:thistlefur-village}Distelfelle{/link} im Norden und die Foulweald im Süden, beide wahnsinnig geworden, und die {link:bloodtooth-camp}Bloodtooth{/link}, die einem wilden König folgen.
• {b}Die {link:satyrs}Satyrn{/link}.{/b} Die Satyrn der Felmusk, der Bleakheart und von {link:xavian}Xavian{/link} verehren Dämonen in den zerstörten Tempeln des Ostens.
• {b}Die {link:naga}Naga{/link}.{/b} Die Wrathtail-Naga suchen den {link:the-zoram-strand}Zoramstrand{/link} und die Gewässer von {link:blackfathom-deeps}Blackfathom{/link} heim.
• {b}Die Dämonen.{/b} Teufelswachen und Höllenbestien streifen noch immer durch den Canyon, in dem {link:mannoroth}Mannoroth{/link} fiel.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die versunkene Stadt.{/b} Bei der Teilung nahm das Meer {link:the-zoram-strand}Zoram{/link}. Ihre Herrscher, ihr Ring und ihre Geheimnisse sanken mit ihr.
• {b}Die Lange Wacht.{/b} Zehntausend Jahre lang bewachten die {link:sentinels}Schildwachen{/link} das Eschental, während die Druiden schliefen, und der Wald wurde tief und still.
• {b}Die Ankunft der {link:orcs}Orcs{/link}.{/b} Im Dritten Krieg kamen die Orcs von {link:grom-hellscream}Grom Hellscream{/link} ins Eschental, um Holz für ihre neue Heimat zu schlagen. Die Schildwachen schlugen zurück, und {link:cenarius}Cenarius{/link} selbst erhob sich, um den Wald zu verteidigen. Grom und seine Krieger tranken aus einer Quelle, die mit dem Blut Mannoroths verunreinigt war, und in dieser Raserei erschlugen sie den Halbgott. Danach, in einem Canyon des östlichen Waldes, erschlug Grom {link:mannoroth}Mannoroth{/link} und befreite sein Volk vom Blutfluch, doch er starb an seinen Wunden.
• {b}Hyjal.{/b} In der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} standen Elfen, Orcs und {link:humans}Menschen{/link} gemeinsam gegen {link:archimonde}Archimonde{/link}, und die Legion wurde zerschlagen. Das Bündnis jenes Tages überdauerte den Sieg nicht.
• {b}Die Gegenwart.{/b} Die {link:horde}Horde{/link} schlägt noch immer die Bäume des Eschentals. Die {link:night-elves}Nachtelfen{/link} haben es nie hingenommen.]=],
		},
		{
			title = "Überlieferungen des Waldes",
			text = [=[• Der Foliant von {link:the-howling-vale}Mel'Thandris{/link}, der an einem zerstörten Schrein nahe der Grenze zum {link:felwood}Teufelswald{/link} aufbewahrt wird, soll bedeutsame Ereignisse von selbst auf seinen Blättern verzeichnen. Niemand versteht, wie.
• Ein {link:furbolgs}Furbolg{/link} namens {link:krolg}Krolg{/link} lebt allein am {link:mystral-lake}Mystralsee{/link}. Er spricht nur mit seinesgleichen, und er gibt den Elfen die Schuld am Untergang seines Volkes.
• Die Jäger von {link:splintertree-post}Splintertree{/link} erzählen von drei großen Bestien des Waldes: dem Bären {link:ursangous}Ursangous{/link}, dem Nachtsäbler {link:shadumbra}Shadumbra{/link} und dem Hippogryphen {link:sharptalon}Sharptalon{/link}. Alle drei zu erlegen ist eine Prüfung für den Wert jedes Jägers.
• Die {link:satyrs}Satyrn{/link} haben den Dryaden den Zweig des {link:cenarius}Cenarius{/link} gestohlen, und die Dryaden haben es ihnen nicht verziehen.]=],
		},
	},
})

Translate("deDE", "astranaar", {
	title = "Astranaar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Astranaar ist die wichtigste Stadt der {link:night-elves}Nachtelfen{/link} im {link:ashenvale}Eschental{/link}. Sie steht auf einer Insel in einem See im Herzen des Waldes, mit dem Ufer durch Brücken aus weißem Stein verbunden. Hier befehligt {link:raene-wolfrunner}Raene Wolfrunner{/link} die {link:sentinels}Schildwachen{/link} der Region, und von hier aus reiten Späher in jeden Winkel des Waldes. Die Stadt hat ein Gasthaus, einen Hippogryphenhorst und einen kleinen Markt elfischer Handwerker. Sie ist auch zu einem Haus der Sorge geworden. Ihre Schildwachen berichten, dass die {link:furbolgs}Furbolgs{/link} im Norden immer zahlreicher werden, ein Kind liegt krank in einem ihrer Häuser, und der Krieg mit der {link:horde}Horde{/link} rückt ihren Brücken mit jeder Jahreszeit näher.]=],
		},
	},
})

Translate("deDE", "maestra-s-post", {
	title = "Maestras Posten",
	aliases = { "Maestra" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Maestras Posten ist ein kleiner Außenposten der Elfen im Nordwesten des Eschentals, an der Straße, die von der {link:darkshore}Dunkelküste{/link} herabführt. Es ist die erste Zuflucht, die ein Reisender aus {link:auberdine}Auberdine{/link} im Wald findet. {link:sentinels}Schildwachen{/link} halten dort Wache, und der Druide {link:orendil-broadleaf}Orendil Broadleaf{/link} mischt dort seine Heilmittel. Ein menschlicher Paladin, {link:delgren-the-purifier}Delgren der Läuterer{/link}, hat den Posten zu seinem Stützpunkt im Krieg gegen den {link:cult-of-the-dark-strand}Kult des Dunklen Strangs{/link} gemacht, und seine Boten bringen Nachschub nach Norden nach Auberdine. Druiden, die gerade aus dem Smaragdgrünen Traum erwacht sind, werden hierher geschickt, um empfangen zu werden.]=],
		},
	},
})

Translate("deDE", "bathran-s-haunt", {
	title = "Bathrans Schlupfwinkel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bathrans Schlupfwinkel ist eine Ruine der Elfen in den nördlichen Hügeln des Eschentals, gleich südlich der Grenze zur {link:darkshore}Dunkelküste{/link}. Eine Pflanze namens Bathranshaar wuchs einst zwischen ihren Steinen, und die Druiden schätzten sie als Heilmittel gegen Krankheiten des Geistes. Die Ruine ist nicht mehr leer. {link:forsaken}Verlassene{/link} haben zwischen den Mauern ein Lager aufgeschlagen, und ihre Kräuterkundigen sammeln, was dort wächst, für eigene Zwecke. Die Druiden von {link:maestra-s-post}Maestras Posten{/link} finden ihre Anwesenheit sehr beunruhigend.]=],
		},
	},
})

Translate("deDE", "the-ruins-of-ordil-aran", {
	title = "Die Ruinen von Ordil'Aran",
	aliases = { "Ordil'Aran" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ordil'Aran ist eine zerfallene Stadt der alten Elfen im nördlichen {link:ashenvale}Eschental{/link}, nordöstlich von {link:maestra-s-post}Maestras Posten{/link}. Ihr Name erinnert an die Zwillingsstädte {link:ameth-aran}Ameth'Aran{/link} und {link:bashal-aran}Bashal'Aran{/link} in der {link:darkshore}Dunkelküste{/link}, die in den Tagen von {link:queen-azshara}Königin Azshara{/link} für die Hochgeborenen erbaut wurden. Nun graben die Hexenmeister des Kults des Dunklen Strangs zwischen ihren Steinen. Einer von ihnen trug einen Seelenstein, der das Geheimnis der Macht des Kults barg, bis {link:delgren-the-purifier}Delgren der Läuterer{/link} einen Streiter aussandte, um ihn an sich zu nehmen.]=],
		},
	},
})

Translate("deDE", "the-zoram-strand", {
	title = "Der Zoramstrand",
	aliases = { "Zoramstrand", "Zoram" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zoramstrand ist die Westküste des Eschentals, ein Ufer aus grauem Sand und zerbrochenen Säulen. Unter den Wellen liegt Zoram, eine Stadt der Elfen, die das Meer in der Großen Teilung verschlang. Zeitalter lang war sie beinahe vergessen. Nun sind die {link:naga}Naga{/link} zu ihr zurückgekehrt, und niemand weiß, was sie suchen. Die Wrathtail-Naga halten mit Hydren an ihrer Seite die Küste und ihre Inseln. Am nördlichen Ende des Strandes öffnet sich ein großer, halb im Meer versunkener Tempel in die Tiefen der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}.]=],
		},
	},
})

Translate("deDE", "zoram-gar-outpost", {
	title = "Zoram'gar-Außenposten",
	aliases = { "Zoram'gar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zoram'gar ist der Außenposten der {link:horde}Horde{/link} am {link:the-zoram-strand}Zoramstrand{/link}, ein Lager von {link:orcs}Orcs{/link} und Trollen auf einer Landzunge am Meer. Er wurde errichtet, um die Westküste des Eschentals für die Horde zu beanspruchen und die {link:naga}Naga{/link} und die Ruinen von {link:blackfathom-deeps}Blackfathom{/link} zu beobachten. {link:karang-amakkar}Karang Amakkar{/link} befehligt ihn. Der Troll {link:je-neu-sancrea}Je'neu Sancrea{/link} vom {link:earthen-ring}Irdenen Ring{/link} erforscht das Meer von seinem Ufer aus. Das Lager ist hart bedrängt. Naga überfallen es, eine große Hydra hat es mehr als einmal angegriffen, und die Distelfell-{link:furbolgs}Furbolgs{/link} stehen zwischen ihm und dem {link:splintertree-post}Splintertreeposten{/link}.]=],
		},
	},
})

Translate("deDE", "lake-falathim", {
	title = "Falathimsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Falathimsee liegt am Fuß der Berge im westlichen {link:ashenvale}Eschental{/link}. Auf seiner Insel stand ein Schrein, in dem die Elfen einst einen leuchtenden Edelstein verwahrten, bis der Schrein überrannt wurde. Die {link:murlocs}Murlocs{/link} des Stammes Saltspittle halten nun das Ufer. Hierher kam der Elf {link:teronis}Teronis{/link} auf der Suche nach dem Edelstein, und hier fanden seine Freunde seinen Leichnam, von Murlocklauen zerrissen, unberührt auf der Insel liegend.]=],
		},
	},
})

Translate("deDE", "the-shrine-of-aessina", {
	title = "Der Schrein von Aessina",
	aliases = { "Schrein von Aessina", "Aessina" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schrein von Aessina ist eine verborgene Lichtung in den Bergen des westlichen Eschentals, von Klippen umschlossen und nur über wenige Pfade zu erreichen. In ihr steht ein Schrein von großer und feiner Macht, an dem sich die Magie des Waldes sammelt. Dryaden wohnen dort, unter ihnen {link:therysil}Therysil{/link} und {link:illiyana}Illiyana{/link}, und die {link:sentinel-melyria-frostshadow}Schildwache Melyria Frostshadow{/link} wacht über {link:moonglade}die Lichtung{/link}. Wer eine Verzauberung erneuern will, kommt, um sein Werk in das Becken zu legen, und wartet auf das Leuchten.]=],
		},
	},
})

Translate("deDE", "fire-scar-shrine", {
	title = "Fire Scar-Schrein",
	aliases = { "Fire Scar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Fire Scar-Schrein ist ein Ort großen Übels im Südwesten des Eschentals. Sein Boden ist verbrannt und seine Bäume sind tot. Hier hat der orcische Hexenmeister {link:ilkrud-magthrull}Ilkrud Magthrull{/link} sein Versteck, und Dämonen folgen seinem Ruf. Ein Dämon namens Akkrilus wandelt zwischen der Asche. Die Elfen hielten Ilkrud einst für ein bloßes Ärgernis. Das änderte sich, als {link:delgren-the-purifier}Delgren der Läuterer{/link} erfuhr, dass der Hexenmeister Aufzeichnungen über die Pläne des Kults des Dunklen Strangs führte.]=],
		},
	},
})

Translate("deDE", "thistlefur-village", {
	title = "Lager der Distelfelle",
	aliases = { "Distelfellfeste", "Distelfelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lager der Distelfelle ist die Heimat der Distelfell-{link:furbolgs}Furbolgs{/link}, nördlich von {link:astranaar}Astranaar{/link}. Ihre Hütten verteilen sich durch die Wälder, und am Ende des Lagers führt eine Höhle namens Distelfellfeste in den Hügel. Die Distelfelle waren nicht immer Feinde, doch sie sind nun verderbt, und ihre Zahl ist in den letzten Monaten stark gewachsen. Die {link:sentinels}Schildwachen{/link} fürchten, dass sie kühn genug werden könnten, Astranaar selbst anzugreifen. Auch die {link:horde}Horde{/link} fürchtet sie, denn das Lager versperrt den Weg zwischen {link:zoram-gar-outpost}Zoram'gar{/link} und {link:splintertree-post}Splintertree{/link}.]=],
		},
	},
})

Translate("deDE", "iris-lake", {
	title = "Irissee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Irissee liegt östlich von {link:astranaar}Astranaar{/link}, ein stilles Gewässer mit einer kleinen Insel in seiner Mitte. Auf dieser Insel ruht ein Stein namens Elunes Träne, und er ist nirgendwo sonst auf der Welt zu finden. Die Druiden sagen, er könne Verderbnis fortwaschen. Als die Tochter von {link:pelturas-whitemoon}Pelturas Whitemoon{/link} krank vor Albträumen lag, war es die Träne des Irissees, die sie linderte.]=],
		},
	},
})

Translate("deDE", "the-ruins-of-stardust", {
	title = "Die Sternenstaubruinen",
	aliases = { "Sternenstaubruinen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Sternenstaubruinen liegen südlich von {link:astranaar}Astranaar{/link}, zwischen den Bäumen des südlichen Waldes. Wenig steht dort außer zerbrochenem Stein. Doch ein bereifter Staub sammelt sich zwischen den Ruinen, und die Druiden wissen, dass er ein Fieber kühlen kann. Der Name des Ortes ist älter als jede Aufzeichnung, und die Elfen sagen nur, er sei nach dem Staub benannt.]=],
		},
	},
})

Translate("deDE", "mystral-lake", {
	title = "Mystralsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Mystralsee ist ein breites Gewässer im südlichen {link:ashenvale}Eschental{/link}, nahe dem Eingang des Steinkrallenpfads, der ins {link:stonetalon-mountains}Steinkrallengebirge{/link} führt. Seine Wasser sind zum Leben erwacht. Besudelte Elementare steigen aus ihnen auf und greifen alles an, was sich nähert, und die Straße zwischen dem Wald und dem Steinkrallengebirge ist so gut wie gesperrt. Ein Pavillon auf dem See blickt auf die elfische Zuflucht an seinem Ufer, und sowohl die {link:sentinels}Schildwachen{/link} als auch die {link:horde}Horde{/link} interessieren sich dafür, wer von dort aus beobachtet. Am Südufer lebt {link:krolg}Krolg{/link}, ein {link:furbolgs}Furbolg{/link}, der der Verderbnis seiner Sippe entkommen ist.]=],
		},
	},
})

Translate("deDE", "silverwind-refuge", {
	title = "Silberwindzuflucht",
	aliases = { "Silberwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Silberwindzuflucht ist ein Dorf der {link:night-elves}Nachtelfen{/link} am Südufer des Mystralsees. Es hat eigene Händler, Lehrer und Alchemisten sowie einen Hippogryphenhorst. {link:sentinel-velene-starstrike}Schildwache Velene Starstrike{/link} befehligt seine Wache. In letzter Zeit hat die Zuflucht keine Ruhe gehabt, denn der See neben ihr füllt sich mit abscheulichen Elementaren. Velene hat erfahren, wer sie erschafft, und sie hat geschworen, dass er dafür bezahlen wird.]=],
		},
	},
})

Translate("deDE", "fallen-sky-lake", {
	title = "Fallenskysee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Fallenskysee liegt im Südosten des Eschentals. Die Elfen sammelten einst Mondsteine an seinem Ufer, Steine, die vom Himmel fielen und die Kraft des Mondes in sich tragen. Dann kamen die Shadethicket. Sie sind verdrehte Treants, und ihr Orakel hat jeden gefallenen Mondstein in seinem eigenen Hort gesammelt. Die Elfen gehen nicht mehr zum See.]=],
		},
	},
})

Translate("deDE", "raynewood-retreat", {
	title = "Raynewood",
	aliases = { "Raynewood" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Raynewood ist ein hochgelegener Hain im Herzen des Eschentals, gekrönt von einem großen Baum desselben Namens. Dryaden, die man die Lachenden Schwestern nennt, spielen auf seinen Lichtungen, und Krieger des {link:cenarius}Cenarius{/link} bewachen seine Pfade. {link:oben-rageclaw}Oben{/link} im Baum wohnt {link:keeper-ordanus}Bewahrer Ordanus{/link}, ein Sohn des Cenarius, der von den Gipfeln des Steinkrallengebirges hierher entrückt wurde, als ein Hexenmeister des Schattenrats ihm nach dem Leben trachtete. Hirsche und große Bären streifen über die Hänge darunter, und der Nachtsäbler {link:shadumbra}Shadumbra{/link} jagt zwischen ihnen.]=],
		},
	},
})

Translate("deDE", "the-howling-vale", {
	title = "Das heulende Tal",
	aliases = { "Heulendes Tal", "Mel'Thandris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das heulende Tal liegt im Norden des Eschentals, nahe der Grenze zum {link:felwood}Teufelswald{/link}. Sein Herz ist der zerstörte Schrein von Mel'Thandris, wo ein seltsamer Foliant aufbewahrt wird. Mel'Thandris selbst segnete seine Seiten, und durch eine Macht, die niemand erklären kann, zeichnen sie die großen Ereignisse des Landes auf. In letzter Zeit haben Wolfsmenschen den Schrein eingenommen. Ihre schaurigen Rufe gaben dem Tal seinen Namen. Der Foliant zeigte den {link:sentinels}Schildwachen{/link}, dass diese Geschöpfe an eine verschwundene Priesterin gebunden sind und an ein Relikt namens {red:scythe-of-elune}Sense von Elune{/red}.]=],
		},
	},
})

Translate("deDE", "night-run", {
	title = "Night Run",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Night Run ist ein von {link:satyrs}Satyrn{/link} gehaltenes Tal im nordöstlichen {link:ashenvale}Eschental{/link}. Seine Tempel sind von Blut getränkt, und selbst erfahrene Krieger finden sie beunruhigend. Hier verbarg der hochgeborene Lord {link:athrikus-narassin}Athrikus Narassin{/link} einen seiner letzten Seelensteine, und die gefangene Seele eines Hochgeborenen wartete darin, bis sie befreit wurde. Die Satyrn von Night Run halten auch Öl, das sie den Warsong gestohlen haben und in ihren Ritualen verbrennen.]=],
		},
	},
})

Translate("deDE", "satyrnaar", {
	title = "Satyrnaar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Satyrnaar ist die Festung der Felmusk-{link:satyrs}Satyrn{/link} im östlichen {link:ashenvale}Eschental{/link}, eine in Teufelsschatten gehüllte Ruine. Es ist einer der Orte, an denen {link:athrikus-narassin}Athrikus Narassin{/link} einen Seelenstein verwahrte und wo eine hochgeborene Seele gefangen lag. Wie {link:night-run}Night Run{/link} und {link:xavian}Xavian{/link} war es einst ein Tempel. Der Paladin {link:delgren-the-purifier}Delgren der Läuterer{/link} hat sagen hören, dass die Geschichte der Satyrn mit der der {link:night-elves}Nachtelfen{/link} verknüpft ist, doch seine Gastgeber wollen nicht darüber sprechen.]=],
		},
	},
})

Translate("deDE", "xavian", {
	title = "Xavian",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Xavian ist eine sagenumwobene Stadt der alten Elfen, eingebettet in {link:razorfen-downs}die Hügel{/link} des östlichen Eschentals. Gelehrte erzählen von ihrem verlorenen Wissen, und es heißt, das Wasser ihres höchsten Wasserfalls berge große Magie. Die {link:satyrs}Satyrn{/link} von Xavian beherrschen nun ihre Ruinen, mit Schurken, Teufelsgeschworenen und Höllenrufern unter ihnen. Ihr Herr, {link:geltharis}Geltharis{/link}, stahl den Dryaden den Zweig des {link:cenarius}Cenarius{/link}. Drei Dryadenschwestern gingen nach Xavian, um ihn zurückzuholen. Nur eine kam lebend heraus, und nicht für lange.]=],
		},
	},
})

Translate("deDE", "forest-song", {
	title = "Forest Song",
	aliases = { "Nightsongwälder" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Forest Song ist ein Schrein der {link:night-elves}Nachtelfen{/link} in den Nightsongwäldern des östlichen Eschentals, nahe der Grenze zu {link:azshara}Azshara{/link}. Der Druide {link:kayneth-stillwind}Kayneth Stillwind{/link} hütet ihn. Von hier aus liest er die Berichte der {link:sentinels}Schildwachen{/link} und durchsucht sie nach Zeichen einer Bosheit, die sich, wie er fürchtet, durch den Wald bewegt. Der Schrein steht nahe den Holzfällerlagern der {link:horde}Horde{/link} und den Satyrruinen von {link:xavian}Xavian{/link}, und seine Druiden schlafen selten ruhig.]=],
		},
	},
})

Translate("deDE", "bough-shadow", {
	title = "Bough Shadow",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bough Shadow ist ein großer Baum im äußersten Nordosten des Eschentals, jenseits von {link:forest-song}Forest Song{/link}. Er ist einer der vier Bäume, die nach Aussage der Druiden Tore zum {link:emerald-dream}Smaragdgrünen Traum{/link} sind. Grüne Drachkin halten unter ihm Wache, und große grüne Drachen kreisen um seine Krone. Sie dulden niemanden in ihrer Nähe, und die Elfen von Forest Song lassen sie in Frieden.]=],
		},
	},
})

Translate("deDE", "splintertree-post", {
	title = "Splintertreeposten",
	aliases = { "Splintertree" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Splintertreeposten ist die Festung der {link:horde}Horde{/link} im östlichen {link:ashenvale}Eschental{/link}, ein ummauertes Lager orcischer Hütten auf einem Hügel über der Straße ins {link:the-barrens}Brachland{/link}. Er schützt die Holzfällerlager der Warsong und die Straßen, auf denen ihr Holz nach Süden gebracht wird. Seine Krieger, Jäger und Händler stammen aus jedem Volk der Horde. {link:mastok-wrilehiss}Mastok Wrilehiss{/link} murrt an seinem Tor, {link:senani-thunderheart}Senani Thunderheart{/link} stellt den jungen Jägern ihre Prüfungen, und {link:ertog-ragetusk}Ertog Ragetusk{/link} plant die Überfälle auf die Elfen. Nur wenige Nächte vergehen dort ohne Alarm.]=],
		},
	},
})

Translate("deDE", "warsong-lumber-camp", {
	title = "Das Holzfällerlager der Warsong",
	aliases = { "Lager der Warsongarbeiter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Holzfällerlager der Warsong liegt im äußersten Osten des Eschentals, nahe dem Fluss, der den Wald von {link:azshara}Azshara{/link} trennt. Hier fällen die Peons des Klans Warsong die großen Bäume der Elfen und schicken das Holz nach Süden, um die {link:horde}Horde{/link} zu bauen und zu befeuern. Goblinschredder dröhnen zwischen den Stümpfen, und Grunzer schützen die Arbeiter vor den Pfeilen der {link:sentinels}Schildwachen{/link}. Dies ist die Arbeit, die {link:grom-hellscream}Grom Hellscream{/link} im Dritten Krieg ins {link:ashenvale}Eschental{/link} brachte, und sie hat nie aufgehört. Das Lager lebt vom Nachschub: Sägeblätter aus {link:ratchet}Ratchet{/link}, Äxte aus {link:booty-bay}Booty Bay{/link}, Öl und Seile, die die {link:satyrs}Satyrn{/link} und {link:furbolgs}Furbolgs{/link} immer wieder stehlen.]=],
		},
	},
})

Translate("deDE", "demon-fall-canyon", {
	title = "Demonfall-Canyon",
	aliases = { "Demonfall-Kamm", "Demonfall", "Felfire Hill" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Demonfall-Canyon ist eine tiefe Schlucht im südöstlichen {link:ashenvale}Eschental{/link}, und sein Name erinnert an die berühmteste Tat des Dritten Krieges. In einem Canyon dieses Waldes trieb {link:grom-hellscream}Grom Hellscream{/link} seine Axt in den Grubenlord {link:mannoroth}Mannoroth{/link} und befreite die {link:orcs}Orcs{/link} vom Blut des Dämons, und dort starb er. Der Canyon ist nicht gereinigt worden. Teufelswachen halten darin Wache, Höllenbestien schwelen zwischen seinen Felsen, und Hunde der Legion jagen auf dem Kamm darüber. Auf dem Felfire Hill im Süden befehligt sie ein Schreckenslord namens Diathorus der Sucher.]=],
		},
	},
})

Translate("deDE", "the-dor-danil-barrow-den", {
	title = "Der Dor'danil-Grabhügel",
	aliases = { "Dor'danil-Grabhügel", "Dor'Danil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Dor'danil-Grabhügel liegt im Südosten des Eschentals, östlich der Straße ins {link:the-barrens}Brachland{/link}. Seine Druiden schliefen einst hier und hüteten ein Stück eines alten Stabes. Dann kamen die Verlassenen. Sie errichteten ein Lager neben den Grabhügeln, brauten ihre Krankheiten und vergifteten die Druiden im Schlaf. Die Geister der Dor'Danil-Druiden erhoben sich, von ihren Körpern getrennt und in den Wahnsinn getrieben, und nun wandeln sie mit den Untoten, die sie töteten, durch die Grabhügel.]=],
		},
	},
})

Translate("deDE", "silverwing-outpost", {
	title = "Außenposten der Silverwing",
	aliases = { "Hain der Silverwing" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Außenposten der Silverwing ist ein Lager der {link:sentinels}Schildwachen{/link} im südlichen {link:ashenvale}Eschental{/link}, zwischen den Bäumen westlich der Holzwege der {link:horde}Horde{/link} gelegen. Seine Vorläuferinnen schleichen durch die Wälder, um die {link:orcs}Orcs{/link} auszuspähen, und seine Kriegerinnen stehen bereit, gegen {link:splintertree-post}Splintertree{/link} zuzuschlagen. {link:duriel-moonfire}Duriel Moonfire{/link} führt ihn. Die Horde betrachtet ihn als Dolch an ihrer Seite, und ihre Plünderer haben geschworen, ihn einzunehmen.]=],
		},
	},
})

Translate("deDE", "bloodtooth-camp", {
	title = "Blutreißers Lager",
	aliases = { "Bloodtooth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Blutreißers Lager ist der Unterschlupf des {link:furbolgs}Furbolgs{/link} {link:ran-bloodtooth}Ran Bloodtooth{/link} und seiner Wachen, im Süden des Eschentals nahe dem Rand des Brachlands. Ran ist der wildeste der verderbten Furbolgs, ein König unter seinesgleichen, und die Verderbnis hat ihn nur stärker gemacht. Selbst andere Furbolgs fürchten, was aus diesem Lager hervorkommt.]=],
		},
	},
})

Translate("deDE", "greenpaw-village", {
	title = "Laubtatzenlichtung",
	aliases = { "Totemhügel der Foulweald" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Laubtatzenlichtung ist die Heimat der Foulweald-{link:furbolgs}Furbolgs{/link}, südlich der Straße östlich von {link:astranaar}Astranaar{/link} und westlich des Falfarren. In ihrem Herzen steht der Totemhügel des Stammes. Die Foulweald sind weniger zahlreich als die {link:thistlefur-village}Distelfelle{/link}, aber wilder, und sie greifen Reisende auf der Straße an. Sowohl die {link:sentinels}Schildwachen{/link} als auch die {link:horde}Horde{/link} haben gegen sie zugeschlagen. Als ein Banner der Horde auf ihrem Hügel aufgepflanzt wurde, kam ihr Häuptling heraus, um die Ehre seines Stammes zu verteidigen, und fiel.]=],
		},
	},
})

Translate("deDE", "raene-wolfrunner", {
	title = "Raene Wolfrunner",
	subtitle = "Befehlshaberin der Schildwachen von Astranaar",
	found = "Astranaar, neben ihren beiden Tieren",
	hint = [=[Sprecht mit der Jägerin, die die Schildwachen von Astranaar befehligt.]=],
	allegiance = "Schildwachen · Darnassus",
	aliases = { "Raene" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Raene Wolfrunner führt die {link:sentinels}Schildwachen{/link} von {link:astranaar}Astranaar{/link}. Sie ist eine Jägerin, die einen Wolf und eine große Katze an ihrer Seite hält, und jeder Bericht aus dem Wald geht durch ihre Hände. Sie ruft bis zur {link:darkshore}Dunkelküste{/link} nach Hilfe, und wer dem Ruf folgt, findet sie ruhig, ernst und in großem Mangel an Kriegern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Raene hält das Herz des Eschentals für die {link:night-elves}Nachtelfen{/link} in einer Zeit, in der ihre Feinde von allen Seiten drängen. Ihr Krieg wird an zwei Fronten zugleich geführt: gegen die {link:horde}Horde{/link} und gegen die Verderbnis, die die {link:furbolgs}Furbolgs{/link} des Waldes zu Bestien gemacht hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Späher und Freiwillige gegen die {link:thistlefur-village}Distelfelle{/link} und die Foulweald.
• Sie übernahm die Arbeit ihres Freundes {link:teronis}Teronis{/link} nach seinem Tod.
• Sie bewahrt den Schädel eines Furbolgkönigs und einen alten Stab an einem Ehrenplatz in {link:astranaar}Astranaar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Der Tod von Teronis",
			hint = [=[Sucht auf einer Insel im Westen nach Nachricht von Raenes verschollenem Freund.]=],
			text = [=[Raenes Freund {link:teronis}Teronis{/link} zog nach Westen zum {link:lake-falathim}Falathimsee{/link} auf der Suche nach einem Edelstein, und er kehrte nicht zurück. Er hatte die Teile eines Stabes gesucht, den ein toter Zauberer namens Dartol geschaffen hatte und von dem er glaubte, er könne die Angriffe der {link:furbolgs}Furbolgs{/link} verlangsamen. Man fand seinen Leichnam auf der Insel, von Murlocklauen zerfetzt. Raene legte ihre Trauer beiseite. Die Zeit der Trauer würde später kommen. Was jetzt zählte, war, dass seine Arbeit nicht vergeudet würde.]=],
		},
		{
			title = "Dartols Stab",
			hint = [=[Sammelt die Teile des Stabes und sucht die Dryade am Mondbrunnen auf.]=],
			text = [=[Anhand der Notizen in {link:teronis}Teronis{/link}' Tagebuch wurden die Teile von Dartols Stab quer durch den Wald aufgespürt: eines von verderbten Treants nahe dem {link:felwood}Teufelswald{/link} bewacht, eines bei den verdammten Druiden von {link:the-dor-danil-barrow-den}Dor'Danil{/link} versteckt. Die Dryade {link:shael-dryn}Shael'dryn{/link} fügte sie zusammen, und ein verborgener Schrein gab dem Stab seine Kraft zurück. Er konnte seinem Träger die Gestalt eines {link:furbolgs}Furbolgs{/link} verleihen. Raene wusste nicht, was Teronis damit vorgehabt hatte. Sie vermutete, dass er hoffte, mit einem Furbolg zu sprechen, der vom Teufelsmoos noch unberührt war.]=],
		},
		{
			title = "Der Schädel von Ran Bloodtooth",
			hint = [=[Erfahrt, was der unverderbte Furbolg von seinesgleichen verlangt.]=],
			text = [=[Der Stab führte zu {link:krolg}Krolg{/link}, einem {link:furbolgs}Furbolg{/link}, der der Verderbnis entkommen war und der den Elfen die Schuld an allem gab, was seinem Volk widerfahren war. Doch Krolg wollte nicht, dass elfische Kinder dafür litten. Er verlangte, dass seine Art selbst für Ordnung unter den Ihren sorge, und so wurde {link:ran-bloodtooth}Ran Bloodtooth{/link}, der wildeste der verderbten Furbolgs, erschlagen. Raene stellte seinen Schädel und Dartols Stab dort auf, wo ganz {link:astranaar}Astranaar{/link} sie sehen konnte, und sagte, {link:teronis}Teronis{/link} wäre stolz.]=],
		},
	},
	mentions = {
		{ text = "Reise ins {link:ashenvale}Eschental{/link}" },
		{ text = "Eine angriffslustige Verteidigung" },
		{ text = "Die Bedrohung eindämmen" },
		{ text = "Raenes Reinigung" },
	},
	bonds = {
		{ id = "teronis", name = "Teronis", note = "ihr Freund, dessen Arbeit sie vollendete" },
		{ id = "shael-dryn", name = "Shael'dryn", note = "half, Dartols Stab neu zu schaffen" },
		{ id = "krolg", name = "Krolg", note = "der Furbolg, der ihrer Sache half" },
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "Feind" },
		{ id = "dal-bloodclaw", name = "Dal Bloodclaw", note = "Feind" },
		{ id = "sentinel-thenysil", name = "Schildwache Thenysil", note = "eine Schildwache unter ihrem Befehl" },
	},
})

Translate("deDE", "teronis", {
	title = "Teronis",
	subtitle = "Sucher von Dartols Stab",
	found = "Die Insel im Falathimsee",
	hint = [=[Sucht nach dem verschollenen Freund der Schildwachen auf einer Insel im Westen.]=],
	allegiance = "Schildwachen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Teronis war ein Freund von {link:raene-wolfrunner}Raene Wolfrunner{/link}, der den {link:sentinels}Schildwachen{/link} des Eschentals half. Er glaubte, dass ein Stab, den der Zauberer Dartol vor langer Zeit geschaffen hatte, die Angriffe der {link:furbolgs}Furbolgs{/link} auf die Elfen verlangsamen könnte. Er ging zum {link:lake-falathim}Falathimsee{/link}, um einen Edelstein dafür zu finden, an einem Schrein, den die {link:murlocs}Murlocs{/link} überrannt hatten. Er kehrte nie zurück. Sein Leichnam wurde auf der Insel gefunden, von Murlocklingen und -klauen zerrissen. Aus Gründen, die niemand versteht, hatten die Murlocs ihn unberührt gelassen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er spürte die Teile von Dartols Stab auf und führte ein Tagebuch über seine Suche.
• Sein Tagebuch führte andere dazu, zu vollenden, was er begonnen hatte.]=],
		},
	},
	mentions = {
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "seine Freundin" },
	},
})

Translate("deDE", "shael-dryn", {
	title = "Shael'dryn",
	subtitle = "Dryade des Mondbrunnens",
	found = [=[Ein Mondbrunnen nördlich der östlichen Straße, östlich des Irissees]=],
	hint = [=[Sucht die Dryade, die einen Mondbrunnen nördlich der Straße östlich des Irissees pflegt.]=],
	allegiance = "Nachtelfen · Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shael'dryn ist eine Dryade, die einen Mondbrunnen im Herzen des Eschentals pflegt. Sie kannte einst Dartols Schöpfung und die Treants, die sie bewachten, doch die Treants sind verderbt worden, und es betrübt sie, dass sie ihnen nicht helfen kann. Als man ihr {link:teronis}Teronis{/link}' Arbeit brachte, verriet sie, wo die Teile des Stabes verborgen waren, fügte den Stab mit eigenen Händen neu zusammen und schickte seinen Träger zu einem verborgenen Schrein, um ihn zu erwecken. Sie lacht leicht, selbst in diesen Tagen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie fügte Dartols Stab aus seinen drei Teilen neu zusammen.
• Sie leitete die Suche nach dem Schlüssel, den die verderbten Treants hüteten.]=],
		},
	},
	mentions = {
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "schickte die Sucher des Stabes zu ihr" },
	},
})

Translate("deDE", "krolg", {
	title = "Krolg",
	subtitle = "Der unverderbte Furbolg",
	found = "Eine einsame Hütte südlich des Mystralsees",
	hint = "Findet den Furbolg, der allein südlich des Mystralsees lebt.",
	allegiance = "Furbolgs",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krolg ist ein {link:furbolgs}Furbolg{/link}, der dem Teufelsmoos und seiner Verderbnis entkommen ist. Er wurde aus seinem Stamm verstoßen, und er lebt allein. Er spricht nur mit seinesgleichen. Krolg gibt den {link:night-elves}Nachtelfen{/link} die Schuld an dem, was den Furbolgs widerfahren ist, und sein Hass brennt. Doch er ist gerecht. Er will nicht, dass elfische Kinder leiden, und er hält daran fest, dass die Furbolgs für ihr eigenes Übel einstehen müssen. Darum verlangte er, dass {link:ran-bloodtooth}Ran Bloodtooth{/link} erschlagen werde.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gab sich einem zu erkennen, der in der Gestalt eines {link:furbolgs}Furbolgs{/link} kam.
• Er forderte den Tod von {link:ran-bloodtooth}Ran Bloodtooth{/link}.]=],
		},
	},
	mentions = {
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
	},
	bonds = {
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "das Übel, das er beendet sehen wollte" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "eine unwissende Verbündete" },
	},
})

Translate("deDE", "ran-bloodtooth", {
	title = "Ran Bloodtooth",
	subtitle = "König der Bloodtooth",
	found = "Blutreißers Lager, im südlichen Eschental",
	hint = [=[Hütet Euch vor dem Furbolgfürsten, dessen Lager nahe dem Südrand des Waldes liegt.]=],
	allegiance = "Furbolgs",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ran Bloodtooth ist der gefürchtetste der verderbten {link:furbolgs}Furbolgs{/link} des Eschentals. Er war machthungrig, bevor die Verderbnis ihn berührte, und die Verderbnis hat ihn nur stärker gemacht. Sein Geist gehört nicht mehr ihm selbst. Sein Hass brennt noch heißer als der von {link:krolg}Krolg{/link}, und er ist eine Bedrohung für jedes Geschöpf des Waldes. Die {link:sentinels}Schildwachen{/link} nannten ihn die wildeste Furbolgbedrohung im {link:ashenvale}Eschental{/link}. Sein Schädel steht nun an einem Ehrenplatz in {link:astranaar}Astranaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Raenes Reinigung" },
		{ text = "Raenes Reinigung" },
	},
	bonds = {
		{ id = "krolg", name = "Krolg", note = "wollte ihn tot sehen" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "bewahrt seinen Schädel" },
	},
})

Translate("deDE", "dal-bloodclaw", {
	title = "Dal Bloodclaw",
	subtitle = "Häuptling der Distelfelle",
	found = "Lager der Distelfelle, nördlich von Astranaar",
	hint = "Sucht den Häuptling der Furbolgs nördlich von Astranaar.",
	allegiance = "Furbolgs · Distelfelle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dal Bloodclaw ist der Häuptling der Distelfell-{link:furbolgs}Furbolgs{/link}. Unter ihm ist der Stamm stark angewachsen, und die Späher von {link:astranaar}Astranaar{/link} fürchten, dass er bald kühn genug sein könnte, die Stadt anzugreifen. {link:raene-wolfrunner}Raene Wolfrunner{/link} verlangte seinen Schädel als Beweis, dass den Distelfellen Einhalt geboten worden war. Sie gab nicht vor, dass dies die Bedrohung beenden würde. Es würde Zeit verschaffen, und Zeit war alles, worauf sie hoffen konnte.]=],
		},
	},
	mentions = {
		{ text = "Die Bedrohung eindämmen" },
