})

Translate("deDE", "shindrell-swiftfire", {
	title = "Shindrell Swiftfire",
	subtitle = "Schildwache von Astranaar",
	found = "Astranaar",
	hint = [=[Sprecht mit der Schildwache, die von Astranaar aus die Küsten bewacht.]=],
	allegiance = "Schildwachen",
	aliases = { "Shindrell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shindrell Swiftfire ist eine Schildwache von {link:astranaar}Astranaar{/link}, die über die Küste und den westlichen Wald wacht. Sie war es, die Krieger gegen die {link:naga}Naga{/link} des Zoramstrands aussandte, denn die Elfen teilen mit den Naga eine Geschichte, die sie nicht wiederholen will. Sie jagt auch dem Gift nach, das die {link:orcs}Orcs{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link} sammeln sollen. Es bereitet ihr keine Freude, Geschöpfe zu töten, die dem Feind unfreiwillig dienen, doch sie tut ihre Pflicht. {link:kayneth-stillwind}Kayneth Stillwind{/link} nennt sie tapfer und scharfsinnig.]=],
		},
