			text = [=[• Sie bekämpft die {link:naga}Naga{/link} des Zoramstrands.
• Sie ging gegen das Pridewing-Gift des Steinkrallengebirges vor.
• Sie berichtet {link:kayneth-stillwind}Kayneth Stillwind{/link} vom Zustand des Waldes.]=],
		},
	},
	mentions = {
		{ text = "Reise nach {link:astranaar}Astranaar{/link}" },
		{ text = "{link:the-zoram-strand}Der Zoramstrand{/link}" },
		{ text = "Pridewings des Steinkrallengebirges" },
		{ text = "{link:kayneth-stillwind}Kayneth Stillwind{/link}" },
	},
	bonds = {
		{ id = "kayneth-stillwind", name = "Kayneth Stillwind", note = "empfängt ihre Berichte" },
	},
})

Translate("deDE", "sentinel-thenysil", {
	title = "Schildwache Thenysil",
