Translate("deDE", "pelturas-whitemoon", {
	title = "Pelturas Whitemoon",
	subtitle = "Vater von Relara",
	found = "Astranaar, am Bett seiner Tochter",
	hint = [=[Findet den Vater in Astranaar, dessen Kind krank darniederliegt.]=],
	allegiance = "Nachtelfen",
	aliases = { "Pelturas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Pelturas Whitemoon ist ein {link:night-elves}Nachtelf{/link} aus {link:astranaar}Astranaar{/link}, dessen Tochter Relara schwer erkrankte. Ihre Krankheit war mehr als eine Krankheit des Körpers. Sie wurde von Albträumen gequält, brannte vor Fieber und wurde von Stunde zu Stunde schwächer. Der Druide {link:orendil-broadleaf}Orendil Broadleaf{/link} schickte ihm ein Heilmittel und nannte ihm weitere, falls es versagen sollte. Pelturas folgte jedem davon.]=],
		},
	},
	chapters = {
		{
			title = "Die Heilung von Relara",
			hint = [=[Sammelt Orendils Heilmittel für das kranke Kind von Astranaar.]=],
			text = [=[Das erste Heilmittel verlangsamte die Krankheit nur. Elunes Träne von der Insel im {link:iris-lake}Irissee{/link} wusch die Albträume fort. Der bereifte Staub der {link:the-ruins-of-stardust}Sternenstaubruinen{/link} brach das Fieber. Zuletzt gab ein gefallener Mondstein, dem Hort des Orakels der Shadethicket entrissen, Relara ihre Kraft zurück. Pelturas gab zum Dank seinen liebsten Besitz fort.]=],
		},
	},
	mentions = {
		{ text = "Orendils Heilmittel" },
		{ text = "Elunes Träne" },
		{ text = "{link:the-ruins-of-stardust}Die Sternenstaubruinen{/link}" },
	},
	bonds = {
		{ id = "orendil-broadleaf", name = "Orendil Broadleaf", note = "schickte die Heilmittel" },
	},
})

Translate("deDE", "orendil-broadleaf", {
	title = "Orendil Broadleaf",
	subtitle = "Heiler von Maestras Posten",
	found = "Maestras Posten",
	hint = [=[Sucht den Heiler von Maestras Posten, dessen Kräuter im ganzen Wald gerühmt werden.]=],
