		{
			title = "Zusammenfassung",
			text = [=[Orendil Broadleaf ist ein Heiler von {link:maestra-s-post}Maestras Posten{/link}, und sein Geschick mit Kräutern ist bis nach {link:astranaar}Astranaar{/link} bekannt. Als er erfuhr, dass ein Kind dort an Geist wie Körper erkrankt war, suchte er nach Bathranshaar, einer Pflanze aus den alten Ruinen im Norden. Er mischte sein Heilmittel und betete, dass es wirken möge. Er erfuhr außerdem zu seiner Bestürzung, dass die Verlassenen nach {link:bathran-s-haunt}Bathrans Schlupfwinkel{/link} gekommen waren.]=],
		},
		{
			title = "Taten",
			text = [=[• Er stellte das Heilmittel für Relara Whitemoon her.
• Er nannte die weiteren Heilmittel, die ihr Vater brauchen würde: Elunes Träne, Sternenstaub und einen gefallenen Mondstein.]=],
		},
	},
	mentions = {
		{ text = "Bathranshaar" },
		{ text = "Orendils Heilmittel" },
	},
	bonds = {
		{ id = "pelturas-whitemoon", name = "Pelturas Whitemoon", note = "der Vater, dem er half" },
	},
})

