Translate("deDE", "kayneth-stillwind", {
	title = "Kayneth Stillwind",
	subtitle = "Druide von Forest Song",
	found = "Forest Song",
	hint = [=[Sucht den Druiden, der im Osten den Schrein von Forest Song hütet.]=],
	allegiance = "Nachtelfen",
	aliases = { "Kayneth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kayneth Stillwind hütet den Schrein von {link:forest-song}Forest Song{/link}. Er fürchtet, dass sich eine Bosheit durch das {link:ashenvale}Eschental{/link} bewegt, und er liest jeden Bericht der {link:sentinels}Schildwachen{/link} nach Zeichen davon. Er fand eines bei den Verlassenen, die sich in die Grabhügel der Elfen schlichen. Während er ihre Gifte prüfte, hatte er eine Vision: die Druiden von {link:the-dor-danil-barrow-den}Dor'Danil{/link}, im Schlaf ermordet und als wahnsinnige Geister auferstanden. Er verlangte, dass ihre Anführer vernichtet würden, damit die anderen Frieden fänden. Er spürte, wie die Qual nachließ, als es getan war.]=],
		},
	},
	chapters = {
		{
			title = "Die Druiden von Dor'Danil",
			hint = "Erfahrt, was die Verlassenen neben den Grabhügeln brauen.",
			text = [=[Die Verlassenen hatten ein Lager beim {link:the-dor-danil-barrow-den}Dor'danil-Grabhügel{/link}, wo sie Gifte und Krankheiten in Flaschen abfüllten. Kayneth glaubte, dass sie Krankheit durch die Lande der Elfen verbreiten wollten. Er hatte recht, und es war noch schlimmer. Die Druiden des Grabhügels waren vergiftet worden, und Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak, einst ihre Anführer, führten nun ein Heer wahnsinniger Geister an. Kayneth nannte ihr Ende eine grimmige Arbeit, denn sie waren nur Opfer.]=],
		},
	},
	mentions = {
		{ text = "Kayneth Stillwind" },
		{ text = "Uralter Geist" },
	},
	bonds = {
		{ id = "shindrell-swiftfire", name = "Shindrell Swiftfire", note = "schickt ihm Berichte" },
	},
})

Translate("deDE", "sentinel-velene-starstrike", {
	title = "Schildwache Velene Starstrike",
	subtitle = "Hüterin der Silberwindzuflucht",
	found = "Silberwindzuflucht",
	hint = [=[Sprecht mit der Schildwache von Silberwind, die über den aufgewühlten See wacht.]=],
	allegiance = "Schildwachen",
	aliases = { "Velene Starstrike", "Velene" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Schildwache Velene Starstrike bewacht die {link:silverwind-refuge}Silberwindzuflucht{/link}. Als die Elementare des Mystralsees verdarben, nutzte sie eine Weissagungsschriftrolle und die Armschienen der Geschöpfe, um zu erfahren, wer sie erschaffen hatte. Die Antwort war ein untoter Magier der {link:horde}Horde{/link}, Sarilus Foulborne, der vom {link:dreadmist-peak}Glutnebelgipfel{/link} im {link:the-barrens}Brachland{/link} aus wirkte. Die Verderbnis des Landes machte sie bereits krank. Dass jemand sie absichtlich vermehrte, war mehr, als sie ertragen wollte.]=],
		},
	},
	mentions = {
		{ text = "Elementare Armschienen" },
		{ text = "Beschwörender Magier" },
	},
	bonds = {
		{ id = "tideress", name = "Tideress", note = "einer der abscheulichen Elementare des Sees" },
	},
})

Translate("deDE", "keeper-ordanus", {
	title = "Bewahrer Ordanus",
	subtitle = "Bewahrer von Raynewood",
	found = "Oben im großen Baum von Raynewood",
	hint = "Steigt zur Krone des großen Baumes von Raynewood hinauf.",
	allegiance = "Cenarius · Nachtelfen",
	aliases = { "Ordanus" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bewahrer Ordanus ist ein Bewahrer des Hains, einer der ältesten Söhne des {link:cenarius}Cenarius{/link}. Er wohnte einst auf dem Gipfel des Steinkrallengebirges, wo die Druiden daran arbeiten, das Land zu heilen. Eine Hexenmeisterin des Schattenrats trachtete ihm dort nach dem Leben, und seine Freunde brachten ihn heimlich fort, hinauf in die Krone des großen Baumes {link:raynewood-retreat}Raynewood{/link} im {link:ashenvale}Eschental{/link}. Die Hexenmeisterin behauptet, ihn vor langer Zeit gekannt zu haben, und nennt ihn so stolz wie die Hochgeborenen.]=],
		},
	},
	chapters = {
		{
			title = "Die Jagd der Hexenmeisterin",
			hint = "Erfahrt, wer den Kopf des Bewahrers sucht.",
			text = [=[{link:braelyn-firehand}Braelyn Firehand{/link}, eine Hexenmeisterin, die einem Herrn in {link:jaedenar}Jaedenar{/link} dient, hasste die Druiden des Steinkrallengebirges dafür, dass sie den Fluss der Magie erstickten. Sie suchte Ordanus mit ihrem Blick und fand ihn: ein großer Baum an einer Wegkreuzung und ein Name, {link:raynewood-retreat}Raynewood{/link}. Sie schickte Mörder der {link:horde}Horde{/link} aus, um ihr seinen Kopf zu bringen.]=],
		},
	},
})

Translate("deDE", "senani-thunderheart", {
	title = "Senani Thunderheart",
	subtitle = "Herrin der Jagd im Eschental",
	found = "Splintertreeposten",
	hint = [=[Sprecht mit der Taurin, die den Jägern von Splintertree ihre Prüfung stellt.]=],
	allegiance = "Horde · Tauren",
	aliases = { "Senani" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Senani Thunderheart ist eine Taurin des Splintertreepostens, die die Tradition der Jagd im {link:ashenvale}Eschental{/link} bewahrt. Drei legendäre Bestien streifen durch den Wald: der Bär {link:ursangous}Ursangous{/link}, der Nachtsäbler {link:shadumbra}Shadumbra{/link} und der Hippogryph {link:sharptalon}Sharptalon{/link}. Sie schickt junge Jäger der {link:horde}Horde{/link} hinter ihnen her, damit sie ihre List erproben und etwas über sich selbst lernen. Sie scheint zu spüren, wer kommt, bevor er eintrifft.]=],
		},
	},
	chapters = {
		{
			title = "Die Jagd im Eschental",
			hint = "Erlegt die drei großen Bestien des Waldes.",
			text = [=[{link:ursangous}Ursangous{/link} hatte viele getötet, und eine Mondsichel auf seiner Pranke zeigte, dass die {link:night-elves}Nachtelfen{/link} ihn abgerichtet hatten. {link:shadumbra}Shadumbra{/link} hatte jeden Weg nach Westen zum {link:the-zoram-strand}Zoramstrand{/link} tödlich gemacht. {link:sharptalon}Sharptalon{/link} hatte lange die Peons der Holzfällerlager in Schrecken versetzt. Als alle drei gefallen waren, nannte Senani den Jäger, der sie erlegt hatte, ein würdiges Kind der Ahnen.]=],
		},
	},
	mentions = {
		{ text = "Die Jagd im {link:ashenvale}Eschental{/link}" },
		{ text = "{link:ursangous}Ursangous{/link}' Pranke" },
		{ text = "Shadumbras Kopf" },
		{ text = "Sharptalons Klaue" },
	},
	bonds = {
		{ id = "ursangous", name = "Ursangous", note = "eine der drei Bestien" },
		{ id = "shadumbra", name = "Shadumbra", note = "eine der drei Bestien" },
		{ id = "sharptalon", name = "Sharptalon", note = "eine der drei Bestien" },
	},
})

Translate("deDE", "ursangous", {
	title = "Ursangous",
	subtitle = "Bär der Jagd im Eschental",
	found = "Der südliche Wald, westlich der Silberwindzuflucht",
	hint = [=[Hütet Euch vor dem großen Bären, der durch die Wälder westlich von Silberwind streift.]=],
