	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ursangous ist einer der mächtigsten Bären des Eschentals und eine der drei Bestien der Jagd im {link:ashenvale}Eschental{/link}. Viele sind unter seinen Klauen gestorben. Auf seiner Pranke ist eine kleine Viertelmondsichel, und die {link:tauren}Tauren{/link} von {link:splintertree-post}Splintertree{/link} deuten sie als Zeichen, dass die {link:night-elves}Nachtelfen{/link} ihn abgerichtet haben. Für die Elfen ist er ein {link:the-night-watch}Wächter{/link} des Waldes. Für die {link:horde}Horde{/link} ist er eine Trophäe.]=],
		},
	},
	mentions = {
		{ text = "Ursangous' Pranke" },
	},
	bonds = {
		{ id = "senani-thunderheart", name = "Senani Thunderheart", note = "rief die Jagd aus" },
	},
})

