			text = [=[Sharptalon ist ein mächtiger Hippogryph des Eschentals, die dritte Bestie der Jagd im {link:ashenvale}Eschental{/link}. Sein Weg kreuzt die Straßen zwischen den Holzfällerlagern und dem {link:splintertree-post}Splintertreeposten{/link}, und lange Zeit versetzte er die Peons, die darauf reisten, in Schrecken. Die {link:horde}Horde{/link} sagt, wer ihn zur Strecke bringe, werde an jedem Lagerfeuer und in jedem Sägewerk des Waldes besungen.]=],
		},
	},
	mentions = {
