Translate("deDE", "mastok-wrilehiss", {
	title = "Mastok Wrilehiss",
	subtitle = "Vom Splintertreeposten",
	found = "Splintertreeposten",
	hint = [=[Sprecht mit dem mürrischen Orc von Splintertree, der wenig Geduld für Nutzlose hat.]=],
	allegiance = "Horde",
	aliases = { "Mastok" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mastok Wrilehiss ist ein {link:orcs}Orc{/link} des Splintertreepostens mit wenig Geduld und scharfer Zunge. Als der {link:mystral-lake}Mystralsee{/link} zum Leben erwachte und die Straße ins {link:stonetalon-mountains}Steinkrallengebirge{/link} sperrte, schickte er Freiwillige aus, um sie freizukämpfen und den Pavillon auf dem See auszukundschaften, von dem aus man die Elfen von {link:silverwind-refuge}Silberwind{/link} beobachten konnte. Als ihm einer von ihnen eine abscheuliche Wasserkugel brachte, spottete er. Dann dachte er an den {link:earthen-ring}Irdenen Ring{/link} und schickte die Kugel zu {link:je-neu-sancrea}Je'neu Sancrea{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[Stillstand im {link:stonetalon-mountains}Steinkrallengebirge{/link}]=],
		},
		{ text = "Das besudelte Element" },
		{ text = "{link:je-neu-sancrea}Je'neu{/link} vom Irdenen Ring" },
	},
	bonds = {
		{ id = "je-neu-sancrea", name = "Je'neu Sancrea", note = "der Schamane, nach dem er schickt" },
		{ id = "tideress", name = "Tideress", note = "Ursprung der abscheulichen Kugel" },
	},
})

Translate("deDE", "tideress", {
	title = "Tideress",
	subtitle = "Besudelter Geist des Mystralsees",
	found = "Mystralsee",
	hint = [=[Hütet Euch vor dem abscheulichen Geist, der aus den Wassern des Mystralsees aufsteigt.]=],
	allegiance = "Elemente",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tideress ist ein besudelter Wasserelementar des Mystralsees, der größte der verderbten Geister, die den See tödlich gemacht haben. Als er fiel, hinterließ er eine leuchtende Kugel aus widerlichem Wasser. {link:je-neu-sancrea}Je'neu Sancrea{/link} vom Irdenen Ring fand die Kugel zutiefst beunruhigend. Viele mächtige Elementare beziehen ihre Kraft durch solche Gegenstände, und dieser war verunreinigt worden.]=],
		},
	},
	mentions = {
		{ text = "Das besudelte Element" },
