	},
})

Translate("deDE", "je-neu-sancrea", {
	title = "Je'neu Sancrea",
	subtitle = "Schamane des Irdenen Rings",
	found = "Zoram'gar-Außenposten, am Meer",
	hint = [=[Sprecht mit dem Troll des Irdenen Rings, der in Zoram'gar die Wellen beobachtet.]=],
	allegiance = "Irdener Ring · Horde",
	aliases = { "Je'neu" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Je'neu Sancrea ist ein trollischer Schamane des {link:earthen-ring}Irdenen Rings{/link}, der im {link:zoram-gar-outpost}Zoram'gar-Außenposten{/link} wohnt. Er erforscht das Wasser und alle {link:elements}Elemente{/link} so eingehend, dass er die Leute um sich herum oft nicht bemerkt. Er kam auf Geheiß des Irdenen Rings an den {link:the-zoram-strand}Zoramstrand{/link}, denn etwas unter dem Meer wendet die Elemente gegen die Welt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Je'neu ist der {link:the-night-watch}Wächter{/link} der {link:horde}Horde{/link} über die {link:blackfathom-deeps}Blackfathom-Tiefe{/link}. Durch ihn erfuhr der Irdene Ring, dass der {link:twilight-s-hammer}Schattenhammer{/link} in den versunkenen Tempel gekommen war und dass er Mächte erwecken wollte, von denen die Schamanen gehofft hatten, sie seien für immer fort.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforschte die besudelte Kugel des Mystralsees.
• Er erfuhr den Namen von {link:lorgus-jett}Lorgus Jett{/link} und forderte seinen Tod.
• Er suchte einen Tiefenkern, der jede elementare Regung in den Ruinen aufzeichnet.
• Er erforschte die Kugel, die den verderbten Elementar {link:baron-aquanis}Baron Aquanis{/link} nährte.]=],
		},
	},
	chapters = {
		{
			title = "Die Saphire von Aku'Mai",
			hint = [=[Erfahrt, warum die Naga in den Tunneln von Blackfathom Kristalle ernten.]=],
			text = [=[In den ersten Tunneln der {link:blackfathom-deeps}Blackfathom-Tiefe{/link} wachsen große Saphirhaufen an den Wänden, und die Geister des Wassers klammern sich an sie. Die {link:naga}Naga{/link} hatten begonnen, sie zu ernten. Je'neu wusste nicht, warum, doch er fürchtete, dass die Kristalle in den falschen Händen eine mächtige Waffe abgeben könnten. Er ließ sie holen, bevor die Naga sie nutzen konnten.]=],
		},
		{
			title = "Treue zu den Alten Göttern",
			hint = "Folgt der feuchten Notiz, die in den Tiefen gefunden wurde.",
			text = [=[Eine zerknitterte Notiz verriet den Rest. Die Priesterinnen der {link:naga}Naga{/link} sollten die Kristalle zu einem Mann namens {link:lorgus-jett}Lorgus Jett{/link} bringen, der ihre Macht nutzen wollte, um ein Wesen namens {link:aku-mai}Aku'Mai{/link} zu erfreuen und es in die Welt zurückzurufen. Er träumte von einem neuen Zeitalter unter der Herrschaft der Alten Götter. Lorgus gehörte dem {link:twilight-s-hammer}Schattenhammer{/link} an. Je'neu war zu schwach, um ihm entgegenzutreten, und er schickte andere in die Tiefen, um ihm ein Ende zu machen.]=],
		},
		{
			title = "Der Tiefenkern",
			hint = "Sucht den Stein, der sich an die Elemente erinnert.",
			text = [=[Der {link:twilight-s-hammer}Schattenhammer{/link} hatte die Moonshrine Ruins in den Tiefen eingenommen. Je'neu verlangte nach dem Tiefenkern, der im Tiefenstein der Ruinen lag, einem Gegenstand, der eine Aufzeichnung jeder Regung der {link:elements}Elemente{/link} bewahrt. Mit ihm und mit der seltsamen Kugel, die den verderbten {link:baron-aquanis}Baron Aquanis{/link} genährt hatte, konnte der Irdene Ring zu erfahren beginnen, was der Kult tat und wie.]=],
		},
	},
	mentions = {
		{ text = "Je'neu vom Irdenen Ring" },
		{ text = "Ärger in den Tiefen" },
	},
	bonds = {
		{ id = "mastok-wrilehiss", name = "Mastok Wrilehiss", note = "schickte ihm die Kugel" },
		{ id = "tideress", name = "Tideress", note = "der besudelte Geist, den er erforschte" },
		{ id = "karang-amakkar", name = "Karang Amakkar", note = "befehligt seinen Außenposten" },
	},
})

Translate("deDE", "karang-amakkar", {
	title = "Karang Amakkar",
	subtitle = "Befehlshaber von Zoram'gar",
	found = "Zoram'gar-Außenposten",
	hint = [=[Sprecht mit dem Orc, der den Außenposten der Horde an der Westküste befehligt.]=],
	allegiance = "Horde",
	aliases = { "Karang" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Karang Amakkar befehligt den {link:zoram-gar-outpost}Zoram'gar-Außenposten{/link}, und er träumt davon, das ganze {link:ashenvale}Eschental{/link} unter der {link:horde}Horde{/link} zu sehen. Die Distelfell-{link:furbolgs}Furbolgs{/link} versperren die Straße zwischen seinem Posten und {link:splintertree-post}Splintertree{/link}, und diese Straße würde es der Horde erlauben, {link:astranaar}Astranaar{/link} zu umgehen. Also schickte er Krieger aus, um sie zu dezimieren. Dann wandte er sich den Foulweald zu. Er gab ein Banner aus, das auf ihrem Totemhügel aufgepflanzt werden sollte, und als ihr Häuptling herauskam, um die Ehre seines Stammes zu verteidigen, wurde der Häuptling erschlagen.]=],
		},
	},
	mentions = {
		{ text = "Zwischen Fels und Distelfell" },
		{ text = "König der Foulweald" },
	},
	bonds = {
		{ id = "chief-murgut", name = "Häuptling Murgut", note = "Feind" },
		{ id = "je-neu-sancrea", name = "Je'neu Sancrea", note = "dient in seinem Außenposten" },
	},
})

