Translate("deDE", "mitsuwa", {
	title = "Mitsuwa",
	subtitle = "Aus Zoram'gar",
	found = "Zoram'gar-Außenposten",
	hint = [=[Sprecht mit der Trollin aus Zoram'gar, die um ihre Sippe trauert.]=],
	allegiance = "Horde · Trolle",
	sections = {
		{
			title = "Zusammenfassung",
